<div class="topbar"><div><h1>Knowledge base</h1><p class="muted" style="margin:4px 0 0">Agents answer from these articles. Usage counts show what customers ask about.</p></div></div>
<div class="grid g2" style="align-items:start"><div class="panel"><h2>Articles</h2><?php foreach ($rows as $r): ?><div class="row spread" style="padding:6px 0;border-bottom:1px solid var(--line-2)"><a href="?edit=<?= (int)$r['id'] ?>"><?= e($r['title']) ?></a><span class="small muted"><?= e($r['category']) ?> · used <?= (int)$r['uses'] ?>× <?= $r['status'] === 'draft' ? '· draft' : '' ?></span></div><?php endforeach; ?></div>
<div><form class="panel" method="post" action="/admin/kb"><?= App\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)($item['id'] ?? 0) ?>"><h2><?= $item ? 'Edit article' : 'New article' ?></h2>
  <div class="field"><label for="ti">Title</label><input id="ti" name="title" type="text" value="<?= e($item['title'] ?? '') ?>" required></div>
  <div class="grid g2"><div class="field"><label for="ca">Category</label><input id="ca" name="category" type="text" value="<?= e($item['category'] ?? 'general') ?>"></div><div class="field"><label for="tg">Tags</label><input id="tg" name="tags" type="text" value="<?= e($item['tags'] ?? '') ?>"></div></div>
  <div class="field"><label for="bo">Content</label><textarea id="bo" name="body" style="min-height:220px" required><?= e($item['body'] ?? '') ?></textarea></div>
  <div class="field"><label for="st">Status</label><select id="st" name="status"><option value="published"<?= ($item['status'] ?? '') !== 'draft' ? ' selected' : '' ?>>published</option><option value="draft"<?= ($item['status'] ?? '') === 'draft' ? ' selected' : '' ?>>draft</option></select></div><button class="btn btn-primary btn-sm">Save</button></form>
  <form class="panel" method="post" enctype="multipart/form-data" action="/admin/kb"><?= App\Csrf::field() ?><h2>Import a document</h2><p class="small muted">Upload .txt, .md or .csv (SOPs, policies, price notes). It's stored as an article.</p><div class="field"><input type="file" name="file" accept=".txt,.md,.csv" required></div><div class="grid g2"><input name="title" type="text" placeholder="Title (optional)"><input name="category" type="text" placeholder="Category" value="sop"></div><button class="btn btn-ghost btn-sm" style="margin-top:10px">Import</button></form></div></div>
